parameters.jsCode:
// The CRM is not ours and its exports are not clean. A trailing space on
// "Contacted " used to drop the lead silently, and a missing email was not
// noticed until Gmail rejected it - by which point a row was written and an
// AI call paid for.
const b = ($input.first().json || {}).body || {};
const str = function (v) { return String(v === undefined || v === null ? '' : v).trim(); };

const lead = {
  lead_id: str(b.lead_id),
  name: str(b.name),
  email: str(b.email).toLowerCase(),
  company: str(b.company),
  pipeline_stage: str(b.pipeline_stage)
};

const problems = [];
if (!lead.lead_id) { problems.push('no lead_id'); }
if (!lead.email) { problems.push('no email address'); }
else if (lead.email.indexOf('@') < 1 || lead.email.indexOf('.', lead.email.indexOf('@')) < 0) {
  problems.push('email does not look like an address');
}
if (lead.pipeline_stage.toLowerCase() !== 'contacted') {
  problems.push('stage is "' + lead.pipeline_stage + '", not Contacted');
}

lead.usable = problems.length === 0;
lead.reject_reason = problems.join('; ');
lead.created_at = new Date().toISOString();

// What the unsubscribe link carries. Not the CRM id: that is guessable, and
// the opt-out endpoint has to stay open to anyone holding the link. It is
// also drawn from an alphabet that survives a URL untouched, so the value
// that comes back is always the value that went out.
let token = '';
try {
  const buf = new Uint8Array(24);
  crypto.getRandomValues(buf);
  token = Array.prototype.map.call(buf, function (b) {
    return ('0' + b.toString(16)).slice(-2);
  }).join('');
} catch (e) {
  // Code node sandboxes vary in what globals they expose. Weaker than
  // getRandomValues, but never empty, and still far from guessable.
  while (token.length < 48) { token += Math.random().toString(36).slice(2); }
  token = token.slice(0, 48);
}
lead.unsub_token = token;
return [{ json: lead }];

