// New Lead Only makes duplicates impossible upstream, so this should find
// exactly one row. It is kept because humans edit the sheet and a duplicate
// can still appear by hand.
const rows = $input.all().filter(function (r) { return r.json && r.json.lead_id; });

if (!rows.length) {
  throw new Error('The welcome email was sent but no sheet row can be found for this lead, so the sequence cannot continue. Check the Leads tab.');
}

// created_at is written RAW so it stays an ISO string and this parse works.
// When Sheets was left to format it, the value came back as a date serial,
// the parse produced NaN, the sort collapsed and this returned the OLDEST row.
rows.sort(function (a, b) {
  return (Date.parse(b.json.created_at) || 0) - (Date.parse(a.json.created_at) || 0);
});

return [rows[0]];

const j = $input.first().json || {};
const msgs = Array.isArray(j.messages) ? j.messages : null;

// Fail CLOSED. Every ambiguity here ends in a real inbox, so if the thread
// cannot be read we stop and tell someone rather than assuming silence and
// sending another email.
if (!msgs) {
  throw new Error('Could not read the Gmail thread, so it is unknown whether the lead replied. Refusing to guess.');
}

// n8n simplifies every thread message before we see it, and simplification
// DELETES labelIds, replacing it with labels: an array of {id, name} objects.
// Reading labelIds returned undefined, so the SENT filter never fired, our own
// welcome email counted as an inbound reply, and every lead was marked Replied
// two days after being written to. Read the objects instead.
const OURS = function (m) {
  const labels = Array.isArray(m.labels) ? m.labels : [];
  return labels.some(function (l) {
    const v = l && (l.id || l.name);
    return v === 'SENT' || v === 'DRAFT';
  });
};

// Anchored to the start of the local part. Testing the whole From header threw
// away real people at addresses like sarah@notificationlabs.com.
const ROBOT = /^(mailer-daemon|postmaster|no-?reply|do-?not-?reply|bounce|auto-?reply)/i;
const localPart = function (m) {
  const addr = (String(m.From || m.from || '').match(/[^\s<>]+@[^\s<>]+/) || [''])[0];
  return addr.split('@')[0].toLowerCase();
};

const inbound = msgs.filter(function (m) {
  if (OURS(m)) { return false; }
  if (ROBOT.test(localPart(m))) { return false; }
  return true;
});

// A hard bounce is not a reply, but it is also not silence - the address is
// dead and two more emails to it would only damage sending reputation.
const bounced = msgs.some(function (m) { return /^(mailer-daemon|postmaster)/i.test(localPart(m)); });

return [{
  json: {
    replied: inbound.length > 0,
    bounced: bounced,
    inbound_count: inbound.length,
    total_messages: msgs.length,
    senders: inbound.map(function (m) { return String(m.From || m.from || 'unknown'); }).slice(0, 5)
  }
}];

