parameters.jsCode:
// Every error output lands here. Without it a lead could be emailed and then
// abandoned mid-sequence with the sheet still saying "New", and nobody would
// find out for days.
const e = $input.first().json || {};

let lead = {};
try { lead = $('Normalise Lead').first().json || {}; } catch (err) { lead = {}; }

let reason = '';
if (typeof e.error === 'string') { reason = e.error; }
else if (e.error && typeof e.error.message === 'string') { reason = e.error.message; }
else if (typeof e.message === 'string') { reason = e.message; }
else { reason = JSON.stringify(e).slice(0, 400); }

return [{
  json: {
    // Unique per run. A bare "UNKNOWN" made every unidentifiable failure
    // match the same row and overwrite the reason before it, so the sheet
    // showed one failure where there had been ten.
    lead_id: lead.lead_id || ('UNKNOWN-' + $execution.id),
    name: lead.name || '',
    email: lead.email || '',
    reason: String(reason).slice(0, 900),
    execution_id: $execution.id
  }
}];

