const b = $input.first().json.body || {};
const raw = String(b.t || '');

// Checked again here. The confirm page is not the only thing that can post
// to this address. Refused, not repaired: a token we cannot match is not a
// token to be tidied up, and quietly changing it is how someone ends up
// filed under a name no suppression check will ever look for.
if (!/^[A-Za-z0-9]{16,64}$/.test(raw)) {
  throw new Error('The unsubscribe link was incomplete or malformed, so there is nobody to remove.');
}
return [{ json: { unsub_token: raw, unsubscribed_at: new Date().toISOString() } }];

const row = $input.first().json || {};
if (!row.email) {
  throw new Error('That unsubscribe link does not match any lead we hold, so there is nobody to remove.');
}
return [{ json: row }];
